using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Accounts.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Accounts.Queries.GetAccountById;public sealed class GetAccountByIdQueryHandler(IAccountRepository repository):IRequestHandler<GetAccountByIdQuery,Result<AccountDto>>{public async Task<Result<AccountDto>>Handle(GetAccountByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<AccountDto>(AccountErrors.NotFound):Result.Success(AccountDto.FromEntity(e));}}
